19	 */
20	@RestControllerAdvice
21	public class GlobalExceptionHandler {
22	
23	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
24	
25	    @ExceptionHandler(ApiException.class)
26	    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
27	        return ResponseEntity.status(ex.status())
28	                .body(new ErrorBody(ex.status().value(), ex.getMessage(), LocalDateTime.now()));
29	    }
30	
31	    @ExceptionHandler(MethodArgumentNotValidException.class)
32	    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
33	        String message = ex.getBindingResult().getFieldErrors().stream()
34	                .map(FieldError::getField)
35	                .distinct()
36	                .collect(Collectors.joining(", ", "参数非法: ", ""));
37	        return ResponseEntity.badRequest()
38	                .body(new ErrorBody(400, message, LocalDateTime.now()));
39	    }
40	
41	    @ExceptionHandler({MissingRequestHeaderException.class, HttpMessageNotReadableException.class})
42	    public ResponseEntity<ErrorBody> handleBadRequest(Exception ex) {
43	        return ResponseEntity.badRequest()
44	                .body(new ErrorBody(400, "参数非法: " + ex.getMessage(), LocalDateTime.now()));
45	    }
46	
47	    @ExceptionHandler(Exception.class)
48	    public ResponseEntity<ErrorBody> handleOther(Exception ex) {
49	        log.error("未处理异常", ex);
50	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
51	                .body(new ErrorBody(500, "服务内部错误", LocalDateTime.now()));
52	    }
53	
54	    /**
55	     * 统一错误响应体。
56	     *
57	     * @param status    HTTP 状态码
58	     * @param message   错误描述
59	     * @param timestamp 发生时间（Asia/Shanghai）
60	     */
61	    public record ErrorBody(int status, String message, LocalDateTime timestamp) {
