80	                                          Callable<ResponseEntity<String>> second) throws Exception {
81	        ExecutorService executor = Executors.newFixedThreadPool(2);
82	        try {
83	            CountDownLatch ready = new CountDownLatch(2);
84	            CountDownLatch start = new CountDownLatch(1);
85	            Future<Integer> f1 = executor.submit(new StatusCall(ready, start, first));
86	            Future<Integer> f2 = executor.submit(new StatusCall(ready, start, second));
87	            assertThat(ready.await(5, TimeUnit.SECONDS)).isTrue();
88	            start.countDown();
89	            return List.of(f1.get(15, TimeUnit.SECONDS), f2.get(15, TimeUnit.SECONDS));
90	        } finally {
91	            executor.shutdownNow();
92	        }
93	    }
